package com.fakrudeenmart.servlet;
import com.fakrudeenmart.service.ReviewService;
import com.fakrudeenmart.util.SessionUtil;
import javax.servlet.http.HttpServletRequest; import java.net.URLEncoder; import java.nio.charset.StandardCharsets;
final class ReviewServletSupport { private ReviewServletSupport(){} static long productId(String raw){try{long id=Long.parseLong(raw==null?"":raw);if(id>0)return id;}catch(NumberFormatException ignored){}throw new ReviewService.ReviewException("Product not found.");} static long reviewId(String raw){try{long id=Long.parseLong(raw==null?"":raw);if(id>0)return id;}catch(NumberFormatException ignored){}throw new ReviewService.ReviewException("Review not found.");} static int rating(String raw){try{return Integer.parseInt(raw==null?"":raw);}catch(NumberFormatException e){throw new ReviewService.ReviewException("Rating must be between 1 and 5.");}} static String productRedirect(HttpServletRequest r,long productId,String key,String value){return r.getContextPath()+"/product?id="+productId+"&"+key+"="+URLEncoder.encode(value,StandardCharsets.UTF_8);} static Long userId(HttpServletRequest r){return SessionUtil.getCurrentUserId(r);} }
